CREATE OR REPLACE FUNCTION public.start_journey(_application_id uuid,_mentor_id uuid DEFAULT NULL,_start_date date DEFAULT CURRENT_DATE) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.start_journey(_application_id,_mentor_id,_start_date) $$;
CREATE OR REPLACE FUNCTION public.hiring7_set_mentor(_id uuid,_mentor uuid DEFAULT NULL) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.hiring7_set_mentor(_id,_mentor) $$;
CREATE OR REPLACE FUNCTION public.hiring7_stage_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; IF NEW.stage_key IS DISTINCT FROM OLD.stage_key AND NEW.stage_key IN ('paused','ended') THEN IF coalesce(btrim(NEW.end_reason),'')='' THEN NEW.end_reason:=nullif(current_setting('hiring7.reason',true),''); END IF; IF coalesce(btrim(NEW.end_reason),'')='' THEN RAISE EXCEPTION 'A reason is required for Paused or Ended'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.hiring7_stage_guard() FROM PUBLIC,anon,authenticated;